using GamePulse.Api.Services;
var n=0;void Check(bool ok,string label){n++;if(!ok)throw new Exception(label);}
NhlStat Stat(string game,string team,long? saves,long? sa,long? ga,long? time)=>new(){GameId=game,TeamId=team,Group="goalie",Statistics=new(){["saves"]=saves,["shotsAgainst"]=sa,["goalsAgainst"]=ga,["toiSeconds"]=time,["wins"]=0,["losses"]=0,["overtimeLosses"]=0}};
var summary=NhlInsights.Aggregate("p","Player","goalie",[Stat("1","a",18,20,2,1800),Stat("2","b",38,40,2,3600)])!;
Check(summary.Games==2&&summary.TeamIds.Length==2,"Traded contributions");
Check(Math.Abs(summary.Rates["savePercentage"]!.Value-56.0/60)<1e-12,"SV percentage weighted by shots");
Check(Math.Abs(summary.Rates["gaa"]!.Value-4.0*3600/5400)<1e-12,"GAA uses seconds");
Check(summary.ObservedRows["saves"]==2,"Observation counts");
var missing=NhlInsights.Aggregate("p","Player","goalie",[Stat("1","a",null,20,2,1800),Stat("2","a",38,40,2,3600)])!;
Check(missing.Totals["saves"]==null&&missing.Rates["savePercentage"]==null,"Missing field propagates");
Check(NhlInsights.Aggregate("p","P","goalie",[])==null,"No invented rows");
var zero=NhlInsights.Aggregate("p","P","goalie",[Stat("1","a",0,0,0,0)])!;
Check(zero.Rates["savePercentage"]==null&&zero.Rates["gaa"]==null,"Zero denominators unknown");
NhlGame Game(string id,int? own,int? opp,string finish,bool home=true,bool final=true)=>new(){Id=id,HomeTeamId=home?"a":"b",AwayTeamId=home?"b":"a",HomeScore=home?own:opp,AwayScore=home?opp:own,Finish=finish,Completed=final};
var games=new[]{Game("1",4,1,"REG"),Game("2",1,2,"REG",false),Game("3",2,3,"OT"),Game("4",1,2,"SO",false),Game("5",4,3,"OT"),Game("6",2,1,"SO"),Game("7",null,null,"Unknown",final:false)};
var r=NhlInsights.Scores("all",games,"a","Regular Season");
Check(r.Wins==3&&r.RegulationLosses==1&&r.OvertimeLosses==2&&r.Points==8,"Modern points and OTL");
Check(r.RegulationWins==1&&r.RegulationOvertimeWins==2,"RW ROW excludes shootouts");
Check(r.GoalsFor==14&&r.GoalsAgainst==12&&r.GoalDifferential==2,"Home away scores");
Check(r.CompletedGames==6&&r.ScheduledGames==7,"Not-final excluded");
Check(Math.Abs(r.PointsPercentage!.Value-8.0/12)<1e-12,"Points percentage");
var unknown=NhlInsights.Scores("unknown",[Game("1",1,2,"Unknown")],"a","Regular Season");
Check(unknown.Points==null&&unknown.UnknownResults==1,"Unknown losing finish not assumed regulation");
unknown=NhlInsights.Scores("unknown win",[Game("1",2,1,"Unknown")],"a","Regular Season");
Check(unknown.Points==2&&unknown.RegulationWins==null&&unknown.RegulationOvertimeWins==null,"Known win points and unknown winning finish");
var noScore=NhlInsights.Scores("missing",[Game("1",null,2,"Unknown")],"a","Regular Season");
Check(noScore.GoalsFor==null&&noScore.GoalDifferential==null&&noScore.Points==null,"Missing scores remain unknown");
Check(NhlInsights.Scores("post",games,"a","Playoffs").Points==null,"No playoff standings points");
Check(NhlInsights.Scores("empty",[],"a","Regular Season").GoalsFor==null,"No games not zero scoring");
var invalid=0;try{NhlInsights.Phase("Regular");}catch(NhlDataException e){if(e.Status==400)invalid++;}try{NhlInsights.Group("pitcher");}catch(NhlDataException e){if(e.Status==400)invalid++;}Check(invalid==2,"Invalid filters rejected");
Console.WriteLine($"{n} NHL calculation checks passed");
